import pandas as pd
import numpy as np
import json
import os

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)

# 2. Calculate KPIs
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25

cumulative_return = (last_close - first_close) / first_close
cagr = (last_close / first_close) ** (1 / years) - 1

df['Daily_Return'] = df['Close'].pct_change()
annualized_volatility = df['Daily_Return'].std() * np.sqrt(252)

df['Rolling_Max'] = df['Close'].cummax()
df['Drawdown'] = df['Close'] / df['Rolling_Max'] - 1
max_drawdown = df['Drawdown'].min()

avg_volume = df['Volume'].mean()

# 3. Prepare data for charts
df_monthly = df.set_index('Date').resample('M').agg({
    'Close': 'last',
    'Volume': 'mean'
}).reset_index()

# Properly compute monthly returns and year returns
df['Year'] = df['Date'].dt.year
annual_returns = df.groupby('Year')['Close'].last().pct_change().dropna()
# for first year, compare last close to first close
first_year_return = (df[df['Year'] == df['Year'].min()]['Close'].iloc[-1] - first_close) / first_close
annual_returns.loc[df['Year'].min()] = first_year_return
annual_returns = annual_returns.sort_index()

# Formatting for JS
dates_monthly = df_monthly['Date'].dt.strftime('%Y-%m-%d').tolist()
close_monthly = df_monthly['Close'].round(2).tolist()
volume_monthly = df_monthly['Volume'].round(0).tolist()

years_list = annual_returns.index.tolist()
annual_returns_list = (annual_returns * 100).round(2).tolist() # in percent

# Drawdown data (monthly to save space)
drawdown_monthly = df.set_index('Date').resample('M')['Drawdown'].min().reset_index()
dd_dates = drawdown_monthly['Date'].dt.strftime('%Y-%m-%d').tolist()
dd_values = (drawdown_monthly['Drawdown'] * 100).round(2).tolist()

# 4. Generate HTML Report
