                data: {json.dumps(volume_monthly)},
                backgroundColor: '#9ca3af'
            }}]
        }},
        options: {{
            responsive: true,
            maintainAspectRatio: false,
            scales: {{
                y: {{ beginAtZero: true, grid: {{ color: '#f3f4f6' }} }},
                x: {{ grid: {{ display: false }}, ticks: {{ maxTicksLimit: 12 }} }}
            }},
            plugins: {{ legend: {{ display: false }} }}
        }}
    }});

