    const annualCtx = document.getElementById('annualReturnChart').getContext('2d');
    const annualData = {json.dumps(annual_returns_list)};
    const annualColors = annualData.map(v => v >= 0 ? '#10b981' : '#ef4444');

    new Chart(annualCtx, {{
        type: 'bar',
        data: {{
            labels: {json.dumps(years_list)},
            datasets: [{{
                label: 'Annual Return (%)',
                data: annualData,
